// Все настройки HouseWatch — здесь (Filter читает их отсюда).
const cfg = {
  BUDGET_RUB: 40000,     // потолок «под ключ» в месяц: аренда + свет + вода
  UTIL_VND: 2500000,     // оценка коммуналки семьи с кондиционером, если она не включена в цену
  MAX_SEA_KM: 1.5,       // до ближайшего пляжа (OSM natural=beach) по прямой
  MAX_BAY_KM: 1.0,       // Дананг, залив Liên Chiểu/Thanh Khê: окраина, порог строже
  MIN_ROOMS: 2,          // спальни (поле rooms в Chotot)
  MIN_PRICE_VND: 4000000,// ниже — почти всегда комнаты/мусор
  EXCLUDE_PREPAY: true,  // выкидывать «đóng 3 / thanh toán 6 tháng» — предоплаты за 3+ мес у нас нет
  MB_MAX_DETAILS: 80,    // Muaban: карточек (и геокодов Nominatim, 1/с) за прогон; на старте ~50, потом единицы
  MAX_ALERTS: 10,        // алертов за один прогон
  DIGEST_PER_CITY: 6,    // строк на город в стартовой сводке
  DROP_PCT: 3,           // алерт о снижении цены от этого %
  DIGEST_VERSION: 3,     // поднять на 1 — сводка придёт заново (увиденное не сбрасывается)
  LLM_MODEL: 'gpt-5-mini', // условия из текста; бесплатный лимит mini-моделей 2.5M токенов/день, см. корневой WORKLOG
  CHATS: ['648226895', '893232025'], // кому слать алерты; каждый должен один раз нажать /start у бота
  CATS: [1010, 1020],    // квартиры, дома
  // Регионы Chotot (старые коды провинций, после слияния 2025 не менялись). pages × 50, свежие сверху.
  REGIONS: [
    { code: 3017, city: 'Дананг', pages: 6 },
    { code: 3016, city: 'Хойан', pages: 1 },
    { code: 7044, city: 'Нячанг / Камрань', pages: 2 },
    { code: 2010, city: 'Вунгтау', pages: 2 },
    { code: 7042, city: 'Фантхьет / Муйне', pages: 1 },
    { code: 7043, city: 'Куинён', pages: 1 },
    { code: 7046, city: 'Туихоа', pages: 1 },
    { code: 5031, city: 'Фукуок', pages: 1 },
  ],
};
// Курс ЦБ: Value рублей за Nominal донгов. Если ЦБ не ответил — запасной курс.
const v = $input.first().json?.Valute?.VND;
const vndPerRub = v && v.Value ? v.Nominal / v.Value : 310;
const maxPrice = Math.round(cfg.BUDGET_RUB * vndPerRub); // с запасом: у кого свет включён, может стоить весь бюджет
const out = [];
for (const r of cfg.REGIONS) for (const cg of cfg.CATS) for (let p = 0; p < r.pages; p++)
  out.push({ json: { cfg, vndPerRub, cg, o: p * 50, region: r.code, price: `${cfg.MIN_PRICE_VND}-${maxPrice}` } });
return out;

// Уведомление о падении воркфлоу. Троттлинг на ноду — 30 мин (как во FlightWatch).
const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ HouseWatch VN упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];

// Muaban.net — второй источник. Списки «cho thuê nhà đất» по городам с фильтром цены.
// Регионы привязаны к кодам Chotot, чтобы Filter подписал город одинаково.
const q = $('Chotot Queries').first().json;
const MB = [
  { slug: 'da-nang', region: 3017, pages: 5 },
  { slug: 'ba-ria-vung-tau', region: 2010, pages: 2 },
  { slug: 'khanh-hoa', region: 7044, pages: 2 },
];
const out = [];
for (const c of MB) for (let p = 1; p <= c.pages; p++)
  out.push({ json: { region: c.region,
    url: `https://muaban.net/bat-dong-san/cho-thue-nha-dat-${c.slug}?price=${q.price}&page=${p}` } });
return out;

// Разбор списков Muaban (__NEXT_DATA__) + грубый отсев до запроса карточек:
// 2+ спальни по атрибутам, не комнаты/офисы, ещё не проверяли (или цена изменилась).
const cfg = $('Chotot Queries').first().json.cfg;
const queries = $('MB Queries').all();
const s = $getWorkflowStaticData('global');
if (!s.mbChecked) s.mbChecked = {};
const now = Date.now();
for (const [k, v] of Object.entries(s.mbChecked)) if (now - v.t > 60 * 864e5) delete s.mbChecked[k];
const BAD_CAT = /trọ|văn\s*phòng|mặt\s*bằng|kho|xưởng|đất/i;
const seen = new Set(), out = [];
let listed = 0;
$input.all().forEach((it, idx) => {
  const html = typeof it.json.data === 'string' ? it.json.data : '';
  const m = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (!m) return;
  let items = [];
  try { items = JSON.parse(m[1]).props.pageProps.classified.items || []; } catch (e) { return; }
  const region = queries[idx]?.json.region;
  for (const i of items) {
    listed++;
    if (seen.has(i.id)) continue; seen.add(i.id);
    const attrs = (i.attributes || []).map(a => a.value || '').join(' ');
    const pn = Number((attrs.match(/(\d+)\s*PN/) || [])[1] || 0);
    if (pn < cfg.MIN_ROOMS || pn > 6 || BAD_CAT.test(i.category_name || '')) continue;
    const prev = s.mbChecked[i.id];
    if (prev && prev.p === i.price) continue;
    out.push({ json: { id: i.id, region, price: i.price, rooms: pn, attrs, title: i.title,
      location: i.location, url: 'https://muaban.net' + i.url } });
  }
});
// Списки пустые — Muaban лёг или сменил разметку. Не падаем: Chotot всё равно отработает.
s.mbListed = listed;
const batch = out.slice(0, cfg.MB_MAX_DETAILS);
for (const b of batch) s.mbChecked[b.json.id] = { p: b.json.price, t: now };
// n8n не запускает следующую ноду на пустом входе — даём пустышку, MB Build её выкинет.
return batch.length ? batch : [{ json: { dummy: true, url: 'https://muaban.net/robots.txt' } }];

// Карточка Muaban: текст, адрес, координаты. Если координат нет — запрос в Nominatim по улице.
const cands = $('MB Parse').all();
// Город и рамка поиска (lon1,lat1,lon2,lat2) для геокодера — по региону Chotot.
const GEO = {
  3017: { city: 'Đà Nẵng', box: '108.05,16.15,108.35,15.93' },
  2010: { city: 'Vũng Tàu', box: '107.03,10.50,107.30,10.30' },
  7044: { city: 'Nha Trang', box: '109.10,12.35,109.25,12.10' },
};
const out = [];
$input.all().forEach((it, idx) => {
  const c = cands[idx]?.json || {};
  if (c.dummy) { out.push({ json: { dummy: true, q: '' } }); return; }
  const html = typeof it.json.data === 'string' ? it.json.data : '';
  let d = {};
  const m = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  try { d = JSON.parse(m[1]).props.pageProps.classified || {}; } catch (e) {}
  const body = String(d.body || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&');
  const address = d.address || c.location || '';
  let lat = null, lon = null;
  const ll = String(d.lat_lng || '').match(/(-?\d+\.\d+)\s*[, ]\s*(-?\d+\.\d+)/);
  if (ll) { lat = +ll[1]; lon = +ll[2]; }
  // Nominatim не понимает «Đường…», «số 12», «Quận…» (районы упразднены в 2025) — оставляем улицу + город.
  // viewbox+bounded: после слияния провинций одноимённые улицы бывшей Quảng Nam тоже «Đà Nẵng».
  const parts = address.split(',').map(x => x.trim()).filter(Boolean);
  const ward = parts.find(p => /^(Phường|Xã)\b/i.test(p)) || '';
  const street = parts.map(p => p.replace(/^(đường|số\s*\d+[a-z/]*|gần|kiệt|hẻm|ngõ)\s*/i, '').replace(/^\d+[a-z/]*\s*/i, '').trim())
    .find(p => p && !/^(phường|xã|quận|huyện|thành phố|tp\.?|thị xã|đà nẵng|khánh hòa|bà rịa)/i.test(p)) || '';
  const G = GEO[c.region] || GEO[3017];
  const q = lat ? '' : `${street || ward}, ${G.city}`;
  out.push({ json: { ...c, body, address, lat, lon, ward, box: G.box,
    size: Number(((c.attrs || '').match(/([\d,.]+)\s*m²/) || [])[1]?.replace(',', '.') || 0) || null,
    toilets: Number(((c.attrs || '').match(/(\d+)\s*WC/) || [])[1] || 0) || null,
    q: q || G.city } });
});
return out;

// Сборка объявлений Muaban в формат Chotot-ad, чтобы Filter обрабатывал оба источника одинаково.
const geo = $('MB Geo').all();
const ads = [];
let noCoords = 0;
$input.all().forEach((it, idx) => {
  const g = geo[idx]?.json;
  if (!g || g.dummy) return;
  let lat = g.lat, lon = g.lon;
  if (lat == null) {
    // Nominatim берём как текст: JSON-массив HTTP-нода разложила бы на items и сбила бы порядок.
    let r = null;
    try { r = JSON.parse(it.json.data || '[]')[0] || null; } catch (e) {}
    if (r && r.lat) { lat = +r.lat; lon = +r.lon; }
  }
  if (lat == null) { noCoords++; return; }
  ads.push({ list_id: 'mb' + g.id, url: g.url, src: 'Muaban', subject: g.title, body: g.body,
    price: g.price, rooms: g.rooms, size: g.size, toilets: g.toilets, latitude: lat, longitude: lon,
    region_v2: g.region, street_name: g.address, ward_name: '', area_name: '', geocoded: g.lat == null });
});
return [{ json: { ads, mbNoCoords: noCoords } }];

// Подставляет в сообщения условия из текста объявлений (ответ GPT) и раздаёт по чатам.
// GPT не ответил / ошибка — сообщения уходят без условий (в карточках — то, что поймали регулярки).
const f = $('Filter').first().json;
const cfg = $('Chotot Queries').first().json.cfg;
const T = {};
let llmOk = false;
try {
  const r = $input.first().json;
  for (const t of JSON.parse(r.choices[0].message.content).items) T[t.id] = t;
  llmOk = true;
} catch (e) { /* фолбэк ниже */ }
// Залог из поля формы Chotot перекрывает GPT: продавец указал его явно. Без ответа GPT — хотя бы залог.
for (const [id, months] of Object.entries(f.dep || {})) T[id] = { ...(T[id] || { pay_every_months: null, min_term_months: null,
  electricity: null, utilities_included: null, furniture: null, real_bedrooms: null, summary_ru: '' }), deposit_months: months };

const m = n => (n == null ? '—' : `${String(n).replace('.', ',')} мес`);
const pay = n => (n == null ? '—' : n === 1 ? 'помесячно' : `раз в ${m(n)}`);
const FURN = { full: 'полная', basic: 'базовая', none: 'без мебели' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Предоплата 3+ мес, найденная GPT (регулярка могла пропустить) — такое нам не подходит.
const bad = t => cfg.EXCLUDE_PREPAY && t && t.pay_every_months >= 3;
const short = t => !t ? '' :
  `\n      ↳ залог ${m(t.deposit_months)} · оплата ${pay(t.pay_every_months)} · срок ${t.min_term_months == null ? '—' : 'от ' + m(t.min_term_months)}` +
  (t.real_bedrooms === 1 ? ' · ⚠️по тексту 1 спальня' : '') + (t.summary_ru ? `\n      ↳ ${esc(t.summary_ru)}` : '');
const block = t =>
  `🔐 Залог: ${m(t.deposit_months)} · оплата: ${pay(t.pay_every_months)} · договор: ${t.min_term_months == null ? 'не указан' : 'от ' + m(t.min_term_months)}\n` +
  (t.pay_every_months === 1 ? '' : t.pay_every_months == null ? '💬 оплату уточнить (нужно помесячно)\n' : '') +
  (t.electricity || t.utilities_included != null ? `⚡ Свет: ${t.utilities_included ? 'включён в цену' : esc(t.electricity || 'не включён, тариф не указан')}\n` : '') +
  (t.furniture ? `🛋 Мебель: ${FURN[t.furniture]}\n` : '') +
  (t.real_bedrooms === 1 ? '⚠️ по тексту реально 1 спальня\n' : '') +
  (t.summary_ru ? `📝 ${esc(t.summary_ru)}\n` : '');

const out = [];
let dropped = 0;
for (const msg of f.msgs) {
  let text = msg.text;
  const before = dropped;
  // Сводка: строки с ⟦L:id⟧…⟦T:id⟧
  let n = 0;
  text = text.split('\n').filter(line => {
    const id = (line.match(/⟦L:([^⟧]+)⟧/) || [])[1];
    if (!id) return true;
    if (bad(T[id])) { dropped++; return false; }
    return true;
  }).map(line => {
    const id = (line.match(/⟦L:([^⟧]+)⟧/) || [])[1];
    if (!id) return line;
    return line.replace(/⟦L:[^⟧]+⟧/, `${++n}. `).replace(/⟦T:[^⟧]+⟧/, short(T[id]));
  }).join('\n');
  // Нумерация по городам: сбрасываем на заголовке блока «<b>Город</b> (N):»
  { let k = 0; text = text.split('\n').map(l => /^<b>.+<\/b> \(\d+\):$/.test(l) ? (k = 0, l) : l.replace(/^\d+\. (?=<a )/, () => `${++k}. `)).join('\n'); }
  // Карточка: ⟦C:id⟧
  const cid = (text.match(/⟦C:([^⟧]+)⟧/) || [])[1];
  if (cid) {
    if (bad(T[cid])) { dropped++; continue; }
    text = text.replace(/⟦C:[^⟧]+⟧/, T[cid] ? block(T[cid]) : ((msg.fallback || {})[cid] || ''));
  }
  text = text.replace(/⟦[LTC]:[^⟧]+⟧/g, '');
  if (!llmOk && /сводка/.test(text)) text += '\n(условия из текста не подтянулись — GPT не ответил)';
  if (dropped > before && /сводка/.test(text)) text += `\n(GPT нашёл в тексте оплату раз в 3+ мес и убрал из списка: ${dropped - before})`;
  out.push({ text, nopreview: msg.nopreview });
}
return out.flatMap(o => cfg.CHATS.map(chat_id => ({ json: { ...o, chat_id } })));
